# owner: platform
"""Weekly timesheet lines, one per worker."""

from hourglass.schedule import worker_minutes
from collections import Counter


def _check(shifts):
    if not shifts:
        raise ValueError("no shifts given")
    for shift in shifts:
        if not shift.worker.strip():
            raise ValueError("shift has no worker name")


def _line(worker, count, minutes):
    return f"{worker}: {count} shifts, {minutes / 60:.1f} h"


def timesheet_lines(shifts):
    """One line per worker, busiest first, ties by name."""
    _check(shifts)
    counts = Counter(shift.worker for shift in shifts)
    totals = worker_minutes(shifts)
    order = sorted(totals, key=lambda w: (-totals[w], w))
    return [_line(w, counts[w], totals[w]) for w in order]

